    window.addEventListener('beforeunload', (evento) => {
        evento.preventDefault();
        evento.returnValue = ''; 
        return ""; 
    });
$(document).ready(function () {


    if (DATOS_USUARIO_DEFINIDOS && !CON_MIGRACION_DATOS_USUARIO) {
        $('#boton-pestana-formulario-datos-acceso').click();
        $('#boton-pestana-formulario-datos-generales').attr('disabled', true);
        $('#boton-regresar-formulario-datos-generales').attr('disabled', true);
    } else {
        $('#boton-regresar-formulario-datos-generales').on('click', function () {
            $('#boton-pestana-formulario-datos-acceso').click();
        });
    }

    $('#formulario-datos-generales').on('submit', async function (evento) {
        $(window).off('beforeunload');
        evento.preventDefault();
        await guardarDatosGenerales($(this).serialize());
    });

    $('#formulario-datos-acceso').on('submit', async function (evento) {
        $(window).off('beforeunload');
        evento.preventDefault();
        await guardarDatosAcceso($(this).serialize());
    });
});

/**
 * Enviar código de autorización.
 *
 * @param {number} id ID del usuario.
 * @returns {Promise<void>}
 * @author Daniel Beltrán
 */
async function enviarCodigoAutorizacion(id) {
    $.ajax({
        type: 'POST',
        url : '/enviar-codigo-autorizacion',
        data: {
            _token: $('meta[name="csrf-token"]').attr('content'),
            id    : id,
            email : $('#email').val()
        }
    }).done(function (respuesta) {
        $('#alerta-error').removeClass('d-block').addClass('d-none');
        $('#alerta-exito').removeClass('d-none').addClass('d-block');
        $('#alerta-exito').html(`Hemos enviado un código de confirmación a <span style="font-weight: bold">${USUARIO_EMAIL}</span>. Revisa tu bandeja de entrada y, si no lo ves, revisa la carpeta de spam. Ingresa el código aquí para confirmar tu dirección de correo.`);
        console.log(respuesta);
    }).fail(function (error) {
        $('#alerta-exito').removeClass('d-block').addClass('d-none');
        $('#alerta-error').removeClass('d-none').addClass('d-block');
        $('#alerta-error').html('Ocurrio un error al intentar enviar el código de verificación por correo electrónico.');
        console.error(error);
    });
}

/**
 * Verificar el código de autorización.
 *
 * @param {number} id ID del usuario.
 * @returns {Promise<void>}
 * @author Daniel Beltrán
 */
async function verificarCodigoAutorizacion(id) {
    $.ajax({
        type: 'POST',
        url : '/verificar-codigo-autorizacion',
        data: {
            _token: $('meta[name="csrf-token"]').attr('content'),
            id    : id,
            codigo: $('#codigo_autorizacion').val()
        }
    }).done(function (respuesta) {
        if (respuesta.message === 'El código no es válido') {
            $('#alerta-exito').removeClass('d-block').addClass('d-none');
            $('#alerta-error').removeClass('d-none').addClass('d-block');
            $('#alerta-error').html('Código de verificación incorrecto, por favor revisa bien la información.');
        } else {
            $('#alerta-error').removeClass('d-block').addClass('d-none');
            $('#alerta-exito').removeClass('d-none').addClass('d-block');
            $('#alerta-exito').html('Cuenta verificada exitosamente.');
        }
        console.log(respuesta);
    }).fail(function (error) {
        $('#alerta-exito').removeClass('d-block').addClass('d-none');
        $('#alerta-error').removeClass('d-none').addClass('d-block');
        $('#alerta-error').html('Ocurrió un error al intentar verificar el código de autorización.');
        console.error(error);
    });
}

/**
 * Guardar los datos generales del usuario.
 *
 * @param {string} datos_serializados_formulario Datos serializados del formulario de datos generales del usuario.
 * @return {Promise<void>}
 * @author Fahibram Cárcamo
 */
async function guardarDatosGenerales(datos_serializados_formulario) {
    await $.ajax({
        type: 'POST',
        url: `/completar-datos-usuario/datos-generales/${USUARIO_ID}`,
        data: datos_serializados_formulario + `&_token=${$('meta[name="csrf-token"]').attr('content')}&_method=PUT&datos_generales=on`
    }).done(function (respuesta, status, xhr) {
        if (xhr && xhr.status >= 200 && xhr.status < 300) {
            mostrarToast('success', 'Datos generales de usuario almacenados con éxito');
            $('#boton-pestana-formulario-datos-acceso').click();
        }
    }).fail(function (error) {
        $('#alerta-exito').removeClass('d-block');
        $('#alerta-exito').addClass('d-none');
        mostrarToast('danger', error.responseJSON.message);
        console.error(error.responseJSON.message);
    });
}

/**
 * Guardar los datos de acceso del usuario.
 *
 * @param {string} datos_serializados_formulario Datos serializados del formulario de datos de acceso del usuario.
 * @return {Promise<void>}
 * @author Fahibram Cárcamo
 */
async function guardarDatosAcceso(datos_serializados_formulario) {
    await $.ajax({
        type: 'POST',
        url : `/completar-datos-usuario/datos-acceso/${USUARIO_ID}`,
        data: datos_serializados_formulario + `&_token=${$('meta[name="csrf-token"]').attr('content')}&_method=PUT&datos_acceso=on`
    }).done(function (respuesta, status, xhr) {
        if (xhr && xhr.status >= 200 && xhr.status < 300) {
            $('#alerta-error').removeClass('d-block').addClass('d-none');
            $('#alerta-exito').removeClass('d-block').addClass('d-none');
            mostrarToast('success', 'Datos de acceso de usuario almacenados con éxito');
            window.location.href = '/recomendaciones';
        }
    }).fail(function (error) {
        $('#alerta-error').removeClass('d-block').addClass('d-none');
        $('#alerta-exito').removeClass('d-block').addClass('d-none');
        mostrarToast('danger', error.responseJSON.message);
        console.error(error.responseJSON.message);
    });
}

